-- Momentum OS — owner-scoped personal workspace reconciliation.
-- Generated by scripts/build-personal-reconcile-sql.ts from server/personalPlan.ts.
-- Additive: no DROP / TRUNCATE / DELETE. Superseded goals and obsolete TODO
-- tasks are archived / cancelled (status change) so history is preserved.
-- Scoped to exactly one verified owner: 6d8e45af-5bb3-4e40-adb3-e605b9972c79

create table if not exists momentum_os.personal_plan_owner (
  user_id text PRIMARY KEY REFERENCES momentum_os.users(id) ON DELETE CASCADE,
  marked_at text NOT NULL
);
alter table momentum_os.speakers add column if not exists reminder_status text NOT NULL DEFAULT 'not_sent';
alter table momentum_os.speakers add column if not exists asset_approval_status text NOT NULL DEFAULT 'pending';

insert into momentum_os.personal_plan_owner(user_id,marked_at)
values ('6d8e45af-5bb3-4e40-adb3-e605b9972c79', now()::text) on conflict do nothing;

update momentum_os.settings
set daily_templates = '[{"title":"Review the daily prospect report","category":"Client Pipeline","priority":"high","estimated_minutes":20,"goalKey":"client-outreach"},{"title":"Send 20 targeted client proposals/outreach messages","category":"Client Pipeline","priority":"high","estimated_minutes":60,"goalKey":"client-outreach"},{"title":"Log outreach actions and follow up responses","category":"Client Pipeline","priority":"high","estimated_minutes":25,"goalKey":"client-outreach"},{"title":"Publish the day''s Graphic Design with AI course promotion","category":"Course Growth","priority":"high","estimated_minutes":20,"goalKey":"course-promotion"},{"title":"Respond to course enquiries and follow up warm leads","category":"Course Growth","priority":"high","estimated_minutes":30,"goalKey":"course-promotion"},{"title":"Research and contact 3 promotional partners for Graphic Design with AI","category":"Course Growth","priority":"high","estimated_minutes":30,"goalKey":"course-partnerships"},{"title":"Review relevant creative and AI industry developments","category":"Personal Brand","priority":"medium","estimated_minutes":20,"goalKey":"personal-brand"},{"title":"Record today''s wins, blockers and tomorrow''s first action","category":"Personal","priority":"low","estimated_minutes":10,"goalKey":"weekly-review"}]', auto_plan = 1, updated_at = now()::text
where user_id = '6d8e45af-5bb3-4e40-adb3-e605b9972c79';

update momentum_os.cycles
set sales_target = 68, revenue_target = 1000000, outreach_target = 20,
    status = 'active', updated_at = now()::text
where user_id = '6d8e45af-5bb3-4e40-adb3-e605b9972c79' and month = '2026-11';

-- Five monthly goals (old superseded rows are archived, never deleted).
update momentum_os.monthly_goals set status='archived', updated_at=now()::text
where user_id='6d8e45af-5bb3-4e40-adb3-e605b9972c79' and status <> 'archived' and title not in (
  'Graphic Design with AI course',
  'Next Chapter',
  'Cartridge',
  'Personal brand and creative development',
  'Client acquisition'
);
with m(title,metric_type,source,target,unit) as (values
  ('Graphic Design with AI course','outcome','sales',68,'paid seats'),
  ('Next Chapter','project','manual',4,'live sessions'),
  ('Cartridge','project','manual',1,'initiative'),
  ('Personal brand and creative development','behaviour','publishing',30,'published days'),
  ('Client acquisition','behaviour','outreach',20,'outreach actions per day')
)
insert into momentum_os.monthly_goals
  (id,user_id,workspace_id,title,description,category,metric_type,source,target,unit,baseline,status,start_date,end_date,notes,created_at,updated_at)
select 'mg-' || md5('6d8e45af-5bb3-4e40-adb3-e605b9972c79' || ':' || m.title), '6d8e45af-5bb3-4e40-adb3-e605b9972c79', 'personal',
  m.title, '', 'November operating plan', m.metric_type, m.source, m.target, m.unit,
  0, 'active', '2026-11-01', '2026-11-30', '', now()::text, now()::text
from m on conflict do nothing;

